-- Biz Done report column configuration.
-- Steps 1-6: "Details-Policy Based" sheet (policyDetails), India (country_id = 1) -- full
--            re-sequence of columns plus new columns and label renames.
-- Steps 7-9: column removals, "Updated Via SQL" and "Total Brokerage Amount". Country-agnostic
--            and cover both detail sheets, so they reach Sri Lanka too.
-- Safe to re-run end to end.

BEGIN;

-- Step 1: Sync the sequence to the current max id so auto-increment does not collide.
SELECT setval(
    pg_get_serial_sequence('public.localization_report_fields', 'id'),
    COALESCE((SELECT MAX(id) FROM public.localization_report_fields), 0)
);

-- Step 1b: Remove the "Remarks" column if a prior run of this script inserted it (no longer wanted).
DELETE FROM public.localization_report_fields_country_map
WHERE report_section = 'bizdone'
  AND activity_section = 'policyDetails'
  AND country_id = 1
  AND field_value = 'remarks';

-- Step 2: Insert master field definitions, skipping any field_key that already exists.
INSERT INTO public.localization_report_fields (field_key, data_type, required, active, entity_type, meta_data, description)
SELECT v.field_key, v.data_type, v.required, v.active, v.entity_type, v.meta_data::jsonb, v.description
FROM (VALUES
    ('crmManager',         'string', false, true, 'COMPANY', NULL, 'Associate CRM (company.associate_crm_id) user full name'),
    ('crmTeamLead',        'string', false, true, 'COMPANY', NULL, 'Associate CRM manager (company.associate_crm_mgr_id) user full name'),
    ('centralOpsTeamLead', 'string', false, true, 'COMPANY', NULL, 'Central OPS team lead (company.central_ops_team_lead_id) user full name'),
    ('centralOpsLead',     'string', false, true, 'COMPANY', NULL, 'Central OPS lead (company.central_ops_lead_id) user full name'),
    ('businessMonth',      'string', false, true, 'POLICY',  NULL, 'Business month (policy.policy_from / endorsement.endorsement_effective_date)'),
    ('dateOfBusiness',     'string', false, true, 'POLICY',  NULL, 'Date of business (policy.date_of_business / endorsement.date_of_business)'),
    ('totalNetPremium',    'number', false, true, 'POLICY',  NULL, 'Total net premium (net_premium + terrorism + other)')
) AS v(field_key, data_type, required, active, entity_type, meta_data, description)
WHERE NOT EXISTS (
    SELECT 1 FROM public.localization_report_fields lrf
    WHERE lrf.field_key = v.field_key
);

-- Step 3: Insert country-map rows for the new policyDetails columns (India). display_order is a placeholder
-- here; Step 6 assigns the final ordering. Skips any field_value already present for this country/section.
INSERT INTO public.localization_report_fields_country_map (
    country_id, regulatory_key_id, report_section, activity_section,
    display_order, field_label, field_alias, field_value, status, meta_data
)
SELECT
    1, lrf.id, 'bizdone', 'policyDetails',
    900, v.field_key, v.field_key, v.field_key, 'active', NULL
FROM (VALUES
    ('crmManager'),
    ('crmTeamLead'),
    ('centralOpsTeamLead'),
    ('centralOpsLead'),
    ('businessMonth'),
    ('dateOfBusiness'),
    ('totalNetPremium')
) AS v(field_key)
JOIN public.localization_report_fields lrf ON lrf.field_key = v.field_key
WHERE NOT EXISTS (
    SELECT 1 FROM public.localization_report_fields_country_map m
    WHERE m.report_section = 'bizdone'
      AND m.activity_section = 'policyDetails'
      AND m.country_id = 1
      AND m.field_value = v.field_key
);

-- Step 4: Rename existing column labels (field_value/data untouched).
UPDATE public.localization_report_fields_country_map m
SET field_label = r.new_label,
    field_alias = r.new_label
FROM (VALUES
    ('customerName',      'companyName'),
    ('parentCompanyName', 'groupCompany'),
    ('policyCategory',    'iirmCategory'),
    ('policyName',        'policyType'),
    ('empName',           'policyOwner')
) AS r(old_label, new_label)
WHERE m.report_section = 'bizdone'
  AND m.activity_section = 'policyDetails'
  AND m.country_id = 1
  AND m.field_label = r.old_label;

-- Step 5: Deactivate columns that should no longer appear in the report:
--   status (duplicate of policyStatus), leadCrm, policyOwnerReportingManager,
--   uniqueExternalReference, uniqueIworkedgeReference, dealConfirmed.
-- Matched on the normalized (lower, alpha-only) field_label.
UPDATE public.localization_report_fields_country_map m
SET status = 'inactive'
WHERE m.report_section = 'bizdone'
  AND m.activity_section = 'policyDetails'
  AND m.country_id = 1
  AND lower(regexp_replace(m.field_label, '[^a-zA-Z]', '', 'g')) IN (
      'status',
      'leadcrm',
      'policyownerreportingmanager',
      'uniqueexternalreference',
      'uniqueiworkedgereference',
      'dealconfirmed'
  );

-- Step 6: Assign the final display order for every column. Matched on the normalized (lower, alpha-only)
-- field_label so case/spacing differences cannot cause a miss. Renamed labels (Step 4) and the new rows
-- (Step 3) are included.
UPDATE public.localization_report_fields_country_map m
SET display_order = o.new_order
FROM (VALUES
    ('serialnumber',                   1),
    ('iirmorganisation',               2),
    ('companyvertical',                3),
    ('sbu',                            4),
    ('vertical',                       5),
    ('department',                     6),
    ('iirmbranch',                     7),
    ('custid',                         8),
    ('companyname',                    9),
    ('customercategory',              10),
    ('groupcompany',                  11),
    ('iirmcategory',                  12),
    ('policygroup',                   13),
    ('policytype',                    14),
    ('incomemonth',                   15),
    ('businessmonth',                 16),
    ('dateofbusiness',                17),
    ('dateofincome',                  18),
    ('policyowner',                   19),
    ('crmmanager',                    20),
    ('crmteamlead',                   21),
    ('accountmanager',                22),
    ('centralopsteamlead',            23),
    ('centralopslead',                24),
    ('inspolno',                      25),
    ('policyfromdate',                26),
    ('policytodate',                  27),
    ('incometype',                    28),
    ('insendno',                      29),
    ('insurer',                       30),
    ('insbranch',                     31),
    ('sharepercentage',               32),
    ('shareamount',                   33),
    ('netpremium',                    34),
    ('terrorism',                     35),
    ('other',                         36),
    ('totalnetpremium',               37),
    ('gstpercentage',                 38),
    ('gst',                           39),
    ('servicetax',                    40),
    ('grosspremium',                  41),
    ('premiumcollected',              42),
    ('brokeragepercentage',           43),
    ('brokerageamount',               44),
    ('terrorismcommissionamount',     45),
    ('terrorismcommissionpercentage', 46),
    ('brokeragecollected',            47),
    ('fees',                          48),
    ('brokerageamountasenteredbyisg', 49),
    ('brokerageamountasperiwork',     50),
    ('policystatus',                  51),
    ('entryiniwork',                  52),
    ('iirmpolno',                     53),
    ('iirmrefno',                     54),
    ('iworkuniqueid',                 55)
) AS o(norm_label, new_order)
WHERE m.report_section = 'bizdone'
  AND m.activity_section = 'policyDetails'
  AND m.country_id = 1
  AND lower(regexp_replace(m.field_label, '[^a-zA-Z]', '', 'g')) = o.norm_label;

-- ---------------------------------------------------------------------------
-- Step 7: Deactivate columns that are no longer wanted.
-- Deliberately NOT filtered by country_id: this must hit India, Sri Lanka, and any country
-- added later. Sri Lanka's rows exist only in the DB (no seed script in repo), so a
-- country-agnostic predicate is the only way to reach them from source control.
--
-- CRM hierarchy (see the joins in service-lib/utils/policy-report.ts):
--   crmTeamLead = leadCrm's reporting manager, crmManager = one level above that.
-- 'crmManager' is dropped; 'crmTeamLead' survives and is relabelled to "CRM Manager"
-- via headerOverrides in service-lib/utils/file-management.utils.ts.
-- ---------------------------------------------------------------------------
UPDATE public.localization_report_fields_country_map
SET status = 'inactive', updated_at = NOW()
WHERE report_section = 'bizdone'
  AND field_value IN (
    'companyVertical',
    'policyGroup',
    'associateCrm',
    'crmManager',
    'centralOpsLead'
  )
  AND status = 'active';

-- ---------------------------------------------------------------------------
-- Step 8: Add "Ingested Mode" as the LAST column of the detail sheets.
-- Derived in service-lib/utils/policy-report.ts from the existing
-- policy.ingested_mode / endorsement.ingested_mode column:
--   'SQL_LOAD' -> 'U' (Upload), anything else -> 'A' (Application).
-- Country-agnostic for the same reason as Step 7.
-- ---------------------------------------------------------------------------

-- Rename in place for DBs where this script already ran as "updatedViaSql":
-- keeps the display_order already assigned and makes the INSERTs below no-ops.
UPDATE public.localization_report_fields
SET field_key = 'ingestedMode',
    description = 'A/U - A = Application, U = Upload (policy.ingested_mode / endorsement.ingested_mode = SQL_LOAD)'
WHERE field_key = 'updatedViaSql';

UPDATE public.localization_report_fields_country_map
SET field_label = 'ingestedMode', field_alias = 'ingestedMode', field_value = 'ingestedMode'
WHERE report_section = 'bizdone' AND field_value = 'updatedViaSql';

INSERT INTO public.localization_report_fields (field_key, data_type, required, active, entity_type, meta_data, description)
SELECT 'ingestedMode', 'string', false, true, 'POLICY', NULL, 'A/U - A = Application, U = Upload (policy.ingested_mode / endorsement.ingested_mode = SQL_LOAD)'
WHERE NOT EXISTS (
    SELECT 1 FROM public.localization_report_fields WHERE field_key = 'ingestedMode'
);

-- One country-map row per (country, detail sheet) that already has bizdone columns.
-- display_order = that group's current max + 1, so it lands last without disturbing the
-- ordering assigned in Step 6.
INSERT INTO public.localization_report_fields_country_map (
    country_id, regulatory_key_id, report_section, activity_section,
    display_order, field_label, field_alias, field_value, status, meta_data
)
SELECT
    g.country_id,
    lrf.id,
    'bizdone',
    g.activity_section,
    g.max_order + 1,
    'ingestedMode', 'ingestedMode', 'ingestedMode',
    'active',
    NULL
FROM (
    SELECT country_id, activity_section, MAX(display_order) AS max_order
    FROM public.localization_report_fields_country_map
    WHERE report_section = 'bizdone'
      AND activity_section IN ('policyDetails', 'coInsurerDetails')
    GROUP BY country_id, activity_section
) g
CROSS JOIN public.localization_report_fields lrf
WHERE lrf.field_key = 'ingestedMode'
  AND NOT EXISTS (
    SELECT 1 FROM public.localization_report_fields_country_map m
    WHERE m.report_section = 'bizdone'
      AND m.activity_section = g.activity_section
      AND m.country_id = g.country_id
      AND m.field_value = 'ingestedMode'
);

-- ---------------------------------------------------------------------------
-- Step 9: Add "Total Brokerage Amount" as the LAST column of the detail sheets.
--   = basic brokerage + SRCC brokerage + terrorism brokerage + fee
-- Terrorism brokerage prefers tc_brokerage_amount (what the app writes today) and falls back
-- to commission_terrorism only on legacy rows -- identified by commission_terrorism differing
-- from terrorism_brokerage_percentage, since new rows receive the same value in both.
-- The two terrorism columns are never added together.
-- For India srcc is null, so it collapses to basic + terrorism + fee. Computed in
-- service-lib/utils/policy-report.ts for both policy and endorsement rows.
-- Countries that already expose totalBrokerageAmount (Sri Lanka) are skipped by the
-- NOT EXISTS and picked up by the reactivation at the end of this step instead.
-- ---------------------------------------------------------------------------
INSERT INTO public.localization_report_fields (field_key, data_type, required, active, entity_type, meta_data, description)
SELECT 'totalBrokerageAmount', 'number', false, true, 'POLICY', NULL, 'Basic + SRCC + TC brokerage + fee (policy / endorsement)'
WHERE NOT EXISTS (
    SELECT 1 FROM public.localization_report_fields WHERE field_key = 'totalBrokerageAmount'
);

INSERT INTO public.localization_report_fields_country_map (
    country_id, regulatory_key_id, report_section, activity_section,
    display_order, field_label, field_alias, field_value, status, meta_data
)
SELECT
    g.country_id,
    lrf.id,
    'bizdone',
    g.activity_section,
    g.max_order + 1,
    'totalBrokerageAmount', 'totalBrokerageAmount', 'totalBrokerageAmount',
    'active',
    NULL
FROM (
    SELECT country_id, activity_section, MAX(display_order) AS max_order
    FROM public.localization_report_fields_country_map
    WHERE report_section = 'bizdone'
      AND activity_section IN ('policyDetails', 'coInsurerDetails',
                           'companySummary', 'policySummary', 'insurerSummary')
    GROUP BY country_id, activity_section
) g
CROSS JOIN public.localization_report_fields lrf
WHERE lrf.field_key = 'totalBrokerageAmount'
  AND NOT EXISTS (
    SELECT 1 FROM public.localization_report_fields_country_map m
    WHERE m.report_section = 'bizdone'
      AND m.activity_section = g.activity_section
      AND m.country_id = g.country_id
      AND m.field_value = 'totalBrokerageAmount'
);

-- Reactivate it wherever it exists but was previously switched off.
UPDATE public.localization_report_fields_country_map
SET status = 'active', updated_at = NOW()
WHERE report_section = 'bizdone'
  AND activity_section IN ('policyDetails', 'coInsurerDetails',
                           'companySummary', 'policySummary', 'insurerSummary')
  AND field_value = 'totalBrokerageAmount'
  AND status <> 'active';

COMMIT;

-- Rollback for Steps 7-9:
--   UPDATE public.localization_report_fields_country_map SET status = 'active'
--   WHERE report_section = 'bizdone'
--     AND field_value IN ('companyVertical','policyGroup','associateCrm','crmManager','centralOpsLead');
--   DELETE FROM public.localization_report_fields_country_map
--   WHERE report_section = 'bizdone' AND field_value = 'ingestedMode';
--   UPDATE public.localization_report_fields_country_map SET status = 'inactive'
--   WHERE report_section = 'bizdone' AND field_value = 'totalBrokerageAmount';


-- ============================================================================
-- Steps 10-11: FINAL column set, order and labels for India & Sri Lanka
-- Policy Details (single source for this feature). Runs after Steps 1-9 above,
-- which create the columns this section orders. Supersedes the interim ordering
-- in Step 6. Display renames are applied in code (POLICY_REPORT_HEADER_OVERRIDES_
-- INDIA / _SRI_LANKA in file-management.utils.ts); this only sets rows, labels,
-- order and active/inactive status. Idempotent. Co-Insurer NOT changed here.
-- ============================================================================

BEGIN;

-- Sync sequence to avoid id collisions on inserts.
SELECT setval(pg_get_serial_sequence('public.localization_report_fields','id'), COALESCE((SELECT MAX(id) FROM public.localization_report_fields),0));

-- Master field defs for any ADD columns that may not exist yet (skip if present).
INSERT INTO public.localization_report_fields (field_key, data_type, required, active, entity_type, meta_data, description)
SELECT v.field_key, v.data_type, v.required, v.active, v.entity_type, NULL, v.description
FROM (VALUES
    ('parentCompanyName','string',false,true,'COMPANY','Parent/group company name'),
    ('businessMonth','string',false,true,'POLICY','Business month'),
    ('dateOfBusiness','string',false,true,'POLICY','Date of business'),
    ('leadCrm','string',false,true,'COMPANY','Lead CRM user'),
    ('crmTeamLead','string',false,true,'COMPANY','Associate CRM manager (shown as CRM Manager)'),
    ('accountManager','string',false,true,'COMPANY','Account manager user'),
    ('centralOpsTeamLead','string',false,true,'COMPANY','Central OPS team lead'),
    ('basicBrokeragePercentage','number',false,true,'POLICY','Basic brokerage percentage'),
    ('iworkUniqueId','string',false,true,'POLICY','Iwork unique id')
) AS v(field_key,data_type,required,active,entity_type,description)
WHERE NOT EXISTS (SELECT 1 FROM public.localization_report_fields lrf WHERE lrf.field_key=v.field_key);

-- =========================== INDIA (country_id 1) ===========================
-- ===== country_id 1, policyDetails =====
INSERT INTO public.localization_report_fields_country_map (country_id, regulatory_key_id, report_section, activity_section, display_order, field_label, field_alias, field_value, status, meta_data) SELECT 1, lrf.id, 'bizdone', 'policyDetails', 1, 'serialNumber', 'serialNumber', 'indexOffset', 'active', NULL FROM public.localization_report_fields lrf WHERE lrf.field_key = 'indexOffset' AND NOT EXISTS (SELECT 1 FROM public.localization_report_fields_country_map m WHERE m.report_section='bizdone' AND m.activity_section='policyDetails' AND m.country_id=1 AND m.field_value='indexOffset');
UPDATE public.localization_report_fields_country_map SET display_order=1, status='active', field_label='serialNumber', field_alias='serialNumber', updated_at=NOW() WHERE report_section='bizdone' AND activity_section='policyDetails' AND country_id=1 AND field_value='indexOffset';
INSERT INTO public.localization_report_fields_country_map (country_id, regulatory_key_id, report_section, activity_section, display_order, field_label, field_alias, field_value, status, meta_data) SELECT 1, lrf.id, 'bizdone', 'policyDetails', 2, 'iirmOrganisation', 'iirmOrganisation', 'empOrganisationName', 'active', NULL FROM public.localization_report_fields lrf WHERE lrf.field_key = 'empOrganisationName' AND NOT EXISTS (SELECT 1 FROM public.localization_report_fields_country_map m WHERE m.report_section='bizdone' AND m.activity_section='policyDetails' AND m.country_id=1 AND m.field_value='empOrganisationName');
UPDATE public.localization_report_fields_country_map SET display_order=2, status='active', field_label='iirmOrganisation', field_alias='iirmOrganisation', updated_at=NOW() WHERE report_section='bizdone' AND activity_section='policyDetails' AND country_id=1 AND field_value='empOrganisationName';
INSERT INTO public.localization_report_fields_country_map (country_id, regulatory_key_id, report_section, activity_section, display_order, field_label, field_alias, field_value, status, meta_data) SELECT 1, lrf.id, 'bizdone', 'policyDetails', 3, 'SBU', 'SBU', 'empSbuName', 'active', NULL FROM public.localization_report_fields lrf WHERE lrf.field_key = 'empSbuName' AND NOT EXISTS (SELECT 1 FROM public.localization_report_fields_country_map m WHERE m.report_section='bizdone' AND m.activity_section='policyDetails' AND m.country_id=1 AND m.field_value='empSbuName');
UPDATE public.localization_report_fields_country_map SET display_order=3, status='active', field_label='SBU', field_alias='SBU', updated_at=NOW() WHERE report_section='bizdone' AND activity_section='policyDetails' AND country_id=1 AND field_value='empSbuName';
INSERT INTO public.localization_report_fields_country_map (country_id, regulatory_key_id, report_section, activity_section, display_order, field_label, field_alias, field_value, status, meta_data) SELECT 1, lrf.id, 'bizdone', 'policyDetails', 4, 'vertical', 'vertical', 'empVerticalName', 'active', NULL FROM public.localization_report_fields lrf WHERE lrf.field_key = 'empVerticalName' AND NOT EXISTS (SELECT 1 FROM public.localization_report_fields_country_map m WHERE m.report_section='bizdone' AND m.activity_section='policyDetails' AND m.country_id=1 AND m.field_value='empVerticalName');
UPDATE public.localization_report_fields_country_map SET display_order=4, status='active', field_label='vertical', field_alias='vertical', updated_at=NOW() WHERE report_section='bizdone' AND activity_section='policyDetails' AND country_id=1 AND field_value='empVerticalName';
INSERT INTO public.localization_report_fields_country_map (country_id, regulatory_key_id, report_section, activity_section, display_order, field_label, field_alias, field_value, status, meta_data) SELECT 1, lrf.id, 'bizdone', 'policyDetails', 5, 'department', 'department', 'empDepartmentName', 'active', NULL FROM public.localization_report_fields lrf WHERE lrf.field_key = 'empDepartmentName' AND NOT EXISTS (SELECT 1 FROM public.localization_report_fields_country_map m WHERE m.report_section='bizdone' AND m.activity_section='policyDetails' AND m.country_id=1 AND m.field_value='empDepartmentName');
UPDATE public.localization_report_fields_country_map SET display_order=5, status='active', field_label='department', field_alias='department', updated_at=NOW() WHERE report_section='bizdone' AND activity_section='policyDetails' AND country_id=1 AND field_value='empDepartmentName';
INSERT INTO public.localization_report_fields_country_map (country_id, regulatory_key_id, report_section, activity_section, display_order, field_label, field_alias, field_value, status, meta_data) SELECT 1, lrf.id, 'bizdone', 'policyDetails', 6, 'iirmBranch', 'iirmBranch', 'empBranchName', 'active', NULL FROM public.localization_report_fields lrf WHERE lrf.field_key = 'empBranchName' AND NOT EXISTS (SELECT 1 FROM public.localization_report_fields_country_map m WHERE m.report_section='bizdone' AND m.activity_section='policyDetails' AND m.country_id=1 AND m.field_value='empBranchName');
UPDATE public.localization_report_fields_country_map SET display_order=6, status='active', field_label='iirmBranch', field_alias='iirmBranch', updated_at=NOW() WHERE report_section='bizdone' AND activity_section='policyDetails' AND country_id=1 AND field_value='empBranchName';
INSERT INTO public.localization_report_fields_country_map (country_id, regulatory_key_id, report_section, activity_section, display_order, field_label, field_alias, field_value, status, meta_data) SELECT 1, lrf.id, 'bizdone', 'policyDetails', 7, 'custId', 'custId', 'companyId', 'active', NULL FROM public.localization_report_fields lrf WHERE lrf.field_key = 'companyId' AND NOT EXISTS (SELECT 1 FROM public.localization_report_fields_country_map m WHERE m.report_section='bizdone' AND m.activity_section='policyDetails' AND m.country_id=1 AND m.field_value='companyId');
UPDATE public.localization_report_fields_country_map SET display_order=7, status='active', field_label='custId', field_alias='custId', updated_at=NOW() WHERE report_section='bizdone' AND activity_section='policyDetails' AND country_id=1 AND field_value='companyId';
INSERT INTO public.localization_report_fields_country_map (country_id, regulatory_key_id, report_section, activity_section, display_order, field_label, field_alias, field_value, status, meta_data) SELECT 1, lrf.id, 'bizdone', 'policyDetails', 8, 'companyName', 'companyName', 'companyName', 'active', NULL FROM public.localization_report_fields lrf WHERE lrf.field_key = 'companyName' AND NOT EXISTS (SELECT 1 FROM public.localization_report_fields_country_map m WHERE m.report_section='bizdone' AND m.activity_section='policyDetails' AND m.country_id=1 AND m.field_value='companyName');
UPDATE public.localization_report_fields_country_map SET display_order=8, status='active', field_label='companyName', field_alias='companyName', updated_at=NOW() WHERE report_section='bizdone' AND activity_section='policyDetails' AND country_id=1 AND field_value='companyName';
INSERT INTO public.localization_report_fields_country_map (country_id, regulatory_key_id, report_section, activity_section, display_order, field_label, field_alias, field_value, status, meta_data) SELECT 1, lrf.id, 'bizdone', 'policyDetails', 9, 'customerCategory', 'customerCategory', 'customerCategory', 'active', NULL FROM public.localization_report_fields lrf WHERE lrf.field_key = 'customerCategory' AND NOT EXISTS (SELECT 1 FROM public.localization_report_fields_country_map m WHERE m.report_section='bizdone' AND m.activity_section='policyDetails' AND m.country_id=1 AND m.field_value='customerCategory');
UPDATE public.localization_report_fields_country_map SET display_order=9, status='active', field_label='customerCategory', field_alias='customerCategory', updated_at=NOW() WHERE report_section='bizdone' AND activity_section='policyDetails' AND country_id=1 AND field_value='customerCategory';
INSERT INTO public.localization_report_fields_country_map (country_id, regulatory_key_id, report_section, activity_section, display_order, field_label, field_alias, field_value, status, meta_data) SELECT 1, lrf.id, 'bizdone', 'policyDetails', 10, 'groupCompany', 'groupCompany', 'parentCompanyName', 'active', NULL FROM public.localization_report_fields lrf WHERE lrf.field_key = 'parentCompanyName' AND NOT EXISTS (SELECT 1 FROM public.localization_report_fields_country_map m WHERE m.report_section='bizdone' AND m.activity_section='policyDetails' AND m.country_id=1 AND m.field_value='parentCompanyName');
UPDATE public.localization_report_fields_country_map SET display_order=10, status='active', field_label='groupCompany', field_alias='groupCompany', updated_at=NOW() WHERE report_section='bizdone' AND activity_section='policyDetails' AND country_id=1 AND field_value='parentCompanyName';
INSERT INTO public.localization_report_fields_country_map (country_id, regulatory_key_id, report_section, activity_section, display_order, field_label, field_alias, field_value, status, meta_data) SELECT 1, lrf.id, 'bizdone', 'policyDetails', 11, 'iirmCategory', 'iirmCategory', 'policyCategory', 'active', NULL FROM public.localization_report_fields lrf WHERE lrf.field_key = 'policyCategory' AND NOT EXISTS (SELECT 1 FROM public.localization_report_fields_country_map m WHERE m.report_section='bizdone' AND m.activity_section='policyDetails' AND m.country_id=1 AND m.field_value='policyCategory');
UPDATE public.localization_report_fields_country_map SET display_order=11, status='active', field_label='iirmCategory', field_alias='iirmCategory', updated_at=NOW() WHERE report_section='bizdone' AND activity_section='policyDetails' AND country_id=1 AND field_value='policyCategory';
